import re
from datetime import datetime, timedelta
from threading import Thread
from apscheduler.schedulers.background import BackgroundScheduler  # type: ignore
from moler.device import DeviceFactory  # type: ignore
from moler.cmd.unix.run_script import RunScript  # type: ignore
from moler.util.moler_test import MolerTest  # type: ignore
from moler.exceptions import CommandFailure, CommandTimeout  # type: ignore
from taf.ul.sc.perf.testline.device_helpers import get_devices_from_regex
from taf.ul.sc.perf.tc.tc_helpers import get_absolute_path
from taf.ul.sc.perf.util.logger import log_debug_function_info
from taf.ul.sc.perf.collectors.periodical_cmds_devices_creator import create_devices_from_regex


class GenericCmds(object):
    def __init__(self, params):
        """

        :param params: dict of pair device_name regex and list of commands(could be pass as list or file)
        """

        self._params = params
        self.params = self._get_adjusted_params()

    @log_debug_function_info()
    def _get_adjusted_params(self):
        params = {}
        for device_regex in self._params:
            device_names = get_devices_from_regex(pattern=device_regex)
            for device_name in device_names:
                new_device_name = "{}_PERIODICAL_CMDS".format(device_name)
                self._create_device_clone(device_name, new_device_name)
                params[new_device_name] = self._get_adjusted_cmds(self._params[device_regex])
            if not device_names:
                device_names = create_devices_from_regex(pattern=device_regex)
                for device_name in device_names:
                    params[device_name] = self._get_adjusted_cmds(self._params[device_regex])

        return params

    @staticmethod
    def _create_device_clone(source_device_name, new_device_name):
        DeviceFactory.get_cloned_device(source_device=source_device_name, new_name=new_device_name)

    @staticmethod
    def _get_adjusted_cmds(param):
        if isinstance(param, list):
            return param
        if isinstance(param, str):
            file_path = get_absolute_path(param)
            if file_path:
                with open(file_path, 'r') as file_object:
                    cmds = file_object.read().splitlines()
                    return cmds
            else:
                return [param]

    @staticmethod
    @log_debug_function_info()
    def _extract_command_and_state(cmd):
        state = None
        match = re.search(r'^\[(?P<STATE>.*)\] (?P<CMD>.*)', cmd)
        if match:
            state = match.group("STATE")
            cmd = match.group("CMD")

        return state, cmd

    def _send_cmd(self, cmd, device):
        state, cmd = self._extract_command_and_state(cmd)
        if state:
            device.goto_state(state)
        try:
            cmd_obj = RunScript(connection=device.io_connection.moler_connection,
                                script_command=cmd,
                                prompt=device.get_prompt())
            cmd_obj()
        except (CommandFailure, CommandTimeout):
            pass

    def _execute_cmd_for_device(self, cmd, device):
        try:
            int(cmd)
            MolerTest.sleep(int(cmd), quiet=True)
        except ValueError:
            self._send_cmd(cmd, device)

    def _execute_cmds_for_device(self, device):
        for cmd in self.params[device.name]:
            self._execute_cmd_for_device(cmd, device)


class OneShotCmds(GenericCmds):
    def __init__(self, params):
        super(OneShotCmds, self).__init__(params)
        self._threads = []

    def start_cmds(self):
        self._define_threads()
        self._start_threads()
        self._wait_for_finish()

    def _define_threads(self):
        for device_name in self.params:
            device = DeviceFactory.get_device(device_name)
            self._threads.append(Thread(target=self._execute_cmds_for_device,
                                        kwargs={'device': device}))

    def _start_threads(self):
        for thread in self._threads:
            thread.start()

    def _wait_for_finish(self):
        for thread in self._threads:
            thread.join()


class PeriodicalCmds(GenericCmds):
    _scheduler = BackgroundScheduler()
    _stop_periodical_cmds = False

    def __init__(self, params, run_date=None):
        super(PeriodicalCmds, self).__init__(params)
        self._validate_params()
        self.jobs = []
        self.run_date = run_date if run_date else datetime.now() + timedelta(seconds=10)

    def start_cmds(self):
        for device_name in self.params:
            device = DeviceFactory.get_device(device_name)
            self.jobs.append(self._scheduler.add_job(func=self._execute_periodical_cmds_for_device,
                                                     kwargs={'device': device},
                                                     trigger='date', run_date=self.run_date))
            PeriodicalCmds._stop_periodical_cmds = False
            if self._scheduler.state == 0:
                self._scheduler.start()

    def stop_cmds(self):
        PeriodicalCmds._stop_periodical_cmds = True
        self._scheduler.shutdown(wait=False)

    def _validate_params(self):
        for device_name in self.params:
            last_cmd = self.params[device_name][-1]
            try:
                int(last_cmd)
            except ValueError:
                raise ValueError("Invalid commands for {}. Last command should be integer but is {}".
                                 format(device_name, last_cmd))

    def _execute_periodical_cmds_for_device(self, device):
        while not PeriodicalCmds._stop_periodical_cmds:
            for cmd in self.params[device.name]:
                if PeriodicalCmds._stop_periodical_cmds:
                    break
                self._execute_cmd_for_device(cmd, device)
